// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }
    function testFuzz_property(uint256 newVal, address actor) public {
        vm.assume(actor != address(0));
        // freeze the pre-initialization value
        uint256 before = c.MinSum();
        vm.prank(actor);
        c.Initialized();
        vm.prank(actor);
        bool ok;
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }
        // In the reference, a post-initialization SetMinSum always reverts (ok == false);
        // and if it ever succeeded, MinSum would still be unchanged.
        assertTrue(!ok || c.MinSum() == before);
    }
}
